<script setup lang="ts">
import { invoke } from "@tauri-apps/api/core";
import { computed, onMounted, ref } from "vue";
import { Calculator, Download, History } from "lucide-vue-next";
import PaginationControls from "../components/PaginationControls.vue";
interface Criterion { code: string; weight: number; raw_value: number; utility_value: number; weighted_contribution: number }
interface Result { variant_id: number; variant_name: string; sku: string; score: number; ranking_position: number; criteria: Criterion[] }
interface Evaluation { evaluation_id: number; period_start: string; period_end: string; results: Result[] }
interface HistoryRow { id: number; period_start: string; period_end: string; evaluated_at: string; costing_method: string; ranking_count: number }
const today = new Date().toISOString().slice(0, 10); const periodStart = ref(`${today.slice(0, 8)}01`); const periodEnd = ref(today); const results = ref<Result[]>([]); const history = ref<HistoryRow[]>([]); const resultPage = ref(1); const historyPage = ref(1); const pageSize = 8; const loading = ref(false); const error = ref(""); const evaluated = ref(false);
const pagedResults = computed(() => results.value.slice((resultPage.value - 1) * pageSize, resultPage.value * pageSize)); const pagedHistory = computed(() => history.value.slice((historyPage.value - 1) * pageSize, historyPage.value * pageSize));
async function loadHistory() { try { history.value = await invoke<HistoryRow[]>("list_smart_history"); historyPage.value = 1; } catch (e) { error.value = String(e); } }
async function evaluate() { loading.value = true; error.value = ""; try { const response = await invoke<Evaluation>("evaluate_smart", { request: { period_start: periodStart.value, period_end: periodEnd.value + "T23:59:59", costing_method: "current recorded purchase price" } }); results.value = response.results; resultPage.value = 1; evaluated.value = true; await loadHistory(); } catch (e) { error.value = String(e); } finally { loading.value = false; } }
function score(value: number) { return `${(value * 100).toFixed(1)}%`; }
function exportCsv() { const rows = [["Ranking", "Varian", "SKU", "Skor", "Keuntungan", "Produk Terjual", "Stok", "Harga Pembelian"], ...results.value.map((result) => { const raw = Object.fromEntries(result.criteria.map((criterion) => [criterion.code, criterion.raw_value])); return [result.ranking_position, result.variant_name, result.sku, result.score, raw.profit ?? "", raw.units_sold ?? "", raw.stock ?? "", raw.purchase_price ?? ""]; })]; const csv = rows.map((row) => row.map((value) => `"${String(value).replace(/"/g, '""')}"`).join(",")).join("\r\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = `siambruk-smart-${periodStart.value}-${periodEnd.value}.csv`; link.click(); URL.revokeObjectURL(url); }
onMounted(loadHistory);
</script>

<template><section class="module-page"><div class="section-intro"><div><p class="eyebrow">Decision support</p><h2>SMART Ranking</h2><p class="intro-copy">Evaluasi transparan per varian dengan kriteria keuntungan, penjualan, stok, dan harga pembelian.</p></div></div><section class="panel evaluation-controls"><div><p class="eyebrow">Periode evaluasi</p><div class="form-row"><label>Mulai<input v-model="periodStart" type="date" /></label><label>Selesai<input v-model="periodEnd" type="date" /></label></div></div><div class="action-row"><button class="secondary-button" :disabled="!results.length" type="button" @click="exportCsv"><Download :size="15" /> CSV</button><button class="primary-button" :disabled="loading" type="button" @click="evaluate"><Calculator :size="15" /> {{ loading ? "Menghitung..." : "Hitung evaluasi" }}</button></div></section><p v-if="error" class="form-error">{{ error }}</p><section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">Hasil tersimpan</p><h3>{{ evaluated ? "Peringkat varian" : "Belum ada evaluasi baru" }}</h3></div><span class="neutral-chip">Bobot tetap 100%</span></div><div v-if="!results.length" class="table-state"><Calculator :size="22" /><strong>Belum ada hasil pada sesi ini</strong><span>Jalankan evaluasi setelah tersedia data varian.</span></div><template v-else><table><thead><tr><th>Peringkat</th><th>Varian</th><th>SKU</th><th>Skor</th><th>Raw · utility · kontribusi</th></tr></thead><tbody><tr v-for="result in pagedResults" :key="result.variant_id"><td class="cell-strong">#{{ result.ranking_position }}</td><td class="cell-strong">{{ result.variant_name }}</td><td>{{ result.sku }}</td><td class="score-cell">{{ score(result.score) }}</td><td><span v-for="criterion in result.criteria" :key="criterion.code" class="criterion-detail"><strong>{{ criterion.code }}</strong> raw {{ criterion.raw_value }} · u {{ score(criterion.utility_value) }} · w {{ score(criterion.weight) }} · {{ score(criterion.weighted_contribution) }}</span></td></tr></tbody></table><PaginationControls v-model:page="resultPage" :total="results.length" :page-size="pageSize" /></template></section><section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">Audit trail</p><h3>Riwayat evaluasi</h3></div><History :size="18" class="panel-icon" /></div><div v-if="!history.length" class="table-state"><span>Belum ada evaluasi tersimpan.</span></div><template v-else><table><thead><tr><th>Periode</th><th>Dibuat</th><th>Metode biaya</th><th>Varian</th></tr></thead><tbody><tr v-for="item in pagedHistory" :key="item.id"><td>{{ item.period_start }} — {{ item.period_end }}</td><td>{{ item.evaluated_at }}</td><td>{{ item.costing_method }}</td><td>{{ item.ranking_count }}</td></tr></tbody></table><PaginationControls v-model:page="historyPage" :total="history.length" :page-size="pageSize" /></template></section></section></template>
